288	// TestSubmitReviewCorruptSpecChangesNothing proves the trailing-data
289	// failure happens entirely in parsing, before any archive state is touched:
290	// no revision is appended, no version moves, and the submission id stays
291	// free for a later complete, legal document.
292	func TestSubmitReviewCorruptSpecChangesNothing(t *testing.T) {
293		dir := t.TempDir()
294		mustReplay(t, dir, twoFindingsInput)
295		good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"r-1","operator":"alice","reason":"r","status":"real","expectedVersion":0}`
296	
297		for _, suffix := range []string{`}`, `]`, ` ` + good, ` x`} {
298			if _, err := ParseReviewSubmission([]byte(good + suffix)); err == nil {
299				t.Fatalf("corrupt spec %q parsed", suffix)
300			}
301		}
302		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
303		if err != nil {
304			t.Fatal(err)
305		}
306		if hist.Version != 0 || hist.Status != ReviewStatusUnreviewed || len(hist.Revisions) != 0 {
307			t.Fatalf("rejected inputs changed review state: %+v", hist)
308		}
309	
310		// The rejected id is not consumed: the complete legal document with the
311		// same id creates version 1 normally.
312		sub, err := ParseReviewSubmission([]byte(good))
313		if err != nil {
314			t.Fatal(err)
315		}
316		res, err := SubmitReview(dir, sub)
317		if err != nil {
318			t.Fatalf("legal resubmit after rejection: %v", err)
319		}
320		if !res.Created || res.Version != 1 {
321			t.Fatalf("legal resubmit = %+v, want created at version 1", res)
322		}
323	
324		// Reusing a stored id with a structurally corrupt document still fails
325		// parsing: it must never come back as the idempotent created:false retry.
326		for _, suffix := range []string{`}`, `]`, ` ` + good} {
327			if _, err := ParseReviewSubmission([]byte(good + suffix)); err == nil {
328				t.Fatalf("corrupt spec reusing stored id %q parsed", suffix)
329			}
330		}
331		hist, err = ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
332		if err != nil {
333			t.Fatal(err)
334		}
335		if hist.Version != 1 || len(hist.Revisions) != 1 {
336			t.Fatalf("corrupt reuse mutated history: %+v", hist)
337		}
338	}
