937	
938	// contenderStatuses gives each racing submitter a status of its own; the
939	// winner revision can then be proven to carry one submitter's complete
940	// content with no fields mixed in from another contender.
941	var contenderStatuses = []string{
942		ReviewStatusFalsePositive,
943		ReviewStatusReal,
944		ReviewStatusUnreviewed,
945	}
946	
947	func raceSub(i int) ReviewSubmission {
948		return reviewSub("1", "0xa", "0xv", "sandwich",
949			fmt.Sprintf("race-%02d", i),
950			fmt.Sprintf("operator-%02d", i),
951			fmt.Sprintf("reason-%02d", i),
952			contenderStatuses[i%len(contenderStatuses)], 1)
953	}
954	
955	type raceOutcome struct {
956		res SubmitReviewResult
957		err error
958	}
959	
960	// runRejudgmentRace fires n contenders carrying the same valid
961	// expectedVersion (1, against an object already at version 1) at the same
962	// instant, each with a distinct submissionId/operator/reason/status, and
963	// returns the per-submitter outcomes in submission order.
964	func runRejudgmentRace(t *testing.T, dir string, n int) []raceOutcome {
965		t.Helper()
966		outcomes := make([]raceOutcome, n)
967		var wg sync.WaitGroup
968		start := make(chan struct{})
969		for i := 0; i < n; i++ {
970			wg.Add(1)
971			go func(i int) {
972				defer wg.Done()
973				<-start
974				outcomes[i].res, outcomes[i].err = SubmitReview(dir, raceSub(i))
975			}(i)
976		}
977		close(start)
978		wg.Wait()
979		return outcomes
980	}
981	
982	// verifyRaceSettlement proves the anti-overwrite rules against the history
983	// actually persisted after a rejudgment race: exactly one contender created
984	// a revision, the object advanced exactly one version, every stored bit of
985	// the new revision comes from that winner alone, the original revision and
986	// the archived conclusion/evidence are untouched, and every loser (busy or
987	// version conflict) left no content behind.
988	func verifyRaceSettlement(t *testing.T, dir string, outcomes []raceOutcome, original ReviewRevision) int {
989		t.Helper()
990		winner := -1
991		busyIdx, conflictIdx := -1, -1
992		for i, o := range outcomes {
993			switch {
994			case o.err == nil:
995				if !o.res.Created || o.res.Version != 2 {
996					t.Fatalf("submitter %d returned %+v, want created at version 2", i, o.res)
997				}
998				if winner != -1 {
999					t.Fatalf("two successful contenders: %d and %d", winner, i)
1000				}
1001				winner = i
1002			case errors.Is(o.err, ErrBusy):
1003				// The contender hit the lock while another submitter held it.
1004				busyIdx = i
1005			case errors.Is(o.err, ErrReviewConflict):
1006				// The contender entered after the lock was released, read the
1007				// already-bumped version and was rejected on the version check.
1008				conflictIdx = i
1009			default:
1010				t.Fatalf("submitter %d got an outcome other than success/busy/conflict: %v", i, o.err)
1011			}
1012		}
1013		if winner == -1 {
1014			t.Fatal("no contender succeeded")
1015		}
1016		t.Logf("race settled: winner=%d, busy=%d, version-conflict=%d (either loser outcome is valid)",
1017			winner, countOutcomes(outcomes, ErrBusy), countOutcomes(outcomes, ErrReviewConflict))
1018	
1019		winSub := raceSub(winner)
1020		wantRev := winSub.revision(2)
1021		if !reflect.DeepEqual(outcomes[winner].res.Revision, wantRev) {
1022			t.Fatalf("winner result revision = %+v, want %+v", outcomes[winner].res.Revision, wantRev)
1023		}
1024	
1025		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1026		if err != nil {
1027			t.Fatal(err)
1028		}
1029		if hist.Version != 2 || hist.Status != winSub.Status {
1030			t.Fatalf("current state = %q/%d, want %q/2 (the winner's rejudgment)",
1031				hist.Status, hist.Version, winSub.Status)
1032		}
1033		if len(hist.Revisions) != 2 {
1034			t.Fatalf("object holds %d revisions, want exactly 2 (losers must leave none): %+v",
1035				len(hist.Revisions), hist.Revisions)
1036		}
1037		if !reflect.DeepEqual(hist.Revisions[0], original) {
1038			t.Fatalf("original revision not retained first: %+v, want %+v", hist.Revisions[0], original)
1039		}
1040		if !reflect.DeepEqual(hist.Revisions[1], wantRev) {
1041			t.Fatalf("appended revision = %+v, want the winner's %+v", hist.Revisions[1], wantRev)
1042		}
1043		// Defense in depth: no field of any loser may appear in the new
1044		// revision, and no loser submission id may be stored anywhere. Status is
1045		// deliberately excluded because only three legal statuses exist so two
1046		// contenders may legitimately carry the same one; identity/operator/
1047		// reason are unique per submitter and the full-revision DeepEqual above
1048		// already pins the winner's status.
1049		loserIDs := map[string]bool{}
1050		for i := range outcomes {
1051			if i == winner {
1052				continue
1053			}
1054			s := raceSub(i)
1055			loserIDs[s.SubmissionID] = true
1056			stored := hist.Revisions[1]
1057			if stored.SubmissionID == s.SubmissionID || stored.Operator == s.Operator ||
1058				stored.Reason == s.Reason {
1059				t.Fatalf("loser %d content mixed into the stored revision: %+v", i, stored)
1060			}
1061			if reflect.DeepEqual(stored, s.revision(2)) {
1062				t.Fatalf("stored revision is identical to loser %d's content: %+v", i, stored)
1063			}
1064		}
1065		for _, rev := range hist.Revisions {
1066			if loserIDs[rev.SubmissionID] {
1067				t.Fatalf("loser submission id %q left a revision", rev.SubmissionID)
1068			}
1069		}
1070		// The original archived conclusion, its detection parameters and the
1071		// raw swap evidence stay exactly as archived.
1072		if hist.Original == nil ||
1073			hist.Original.Finding.TxHash != "0xv" || hist.Original.Finding.Kind != "sandwich" ||
1074			hist.Original.Finding.Severity != 3 || len(hist.Original.Finding.Evidence) != 3 {
1075			t.Fatalf("original conclusion/evidence changed: %+v", hist.Original)
1076		}
1077		if hist.Original.Version.ID != BuiltinVersionID {
1078			t.Fatalf("detection version changed: %+v", hist.Original.Version)
1079		}
1080	
1081		// After the race, resubmitting with the stale expected version must be a
1082		// version conflict regardless of how the contender originally lost: a
1083		// busy loss is not a completed rejudgment, and neither path may overwrite
1084		// the winner.
1085		recheck := func(idx int, label string) {
1086			if idx < 0 {
1087				return
1088			}
1089			if _, err := SubmitReview(dir, raceSub(idx)); !errors.Is(err, ErrReviewConflict) {
1090				t.Fatalf("%s loser (submitter %d) replayed with original expected version: got %v, want ErrReviewConflict",
1091					label, idx, err)
1092			}
1093		}
1094		recheck(busyIdx, "busy")
1095		recheck(conflictIdx, "conflict")
1096		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 1)); !errors.Is(err, ErrReviewConflict) {
1097			t.Fatalf("fresh follower with stale base: got %v, want ErrReviewConflict", err)
1098		}
1099	
1100		// Deterministic late entrants: sequential submissions issued only after
1101		// the object is provably at version 2 and the race lock is long released.
1102		// Each acquires the free lock, reads the already-bumped version and must
1103		// take the version-conflict path (never busy, since submissions are
1104		// serialized here). This is the legitimate loser outcome the old
1105		// regression assumed could never happen, and it must append nothing.
1106		const lateN = 6
1107		for j := 0; j < lateN; j++ {
1108			_, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
1109				fmt.Sprintf("late-%02d", j),
1110				fmt.Sprintf("late-operator-%02d", j),
1111				fmt.Sprintf("late-reason-%02d", j),
1112				contenderStatuses[j%len(contenderStatuses)], 1))
1113			if !errors.Is(err, ErrReviewConflict) {
1114				t.Fatalf("late entrant %d after lock release: got %v, want ErrReviewConflict", j, err)
1115			}
1116		}
1117	
1118		// The follow-up conflict submissions appended nothing either.
1119		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1120		if err != nil {
1121			t.Fatal(err)
1122		}
1123		if final.Version != 2 || len(final.Revisions) != 2 || !reflect.DeepEqual(final.Revisions, hist.Revisions) {
1124			t.Fatalf("post-race conflict replays changed history: %+v", final)
1125		}
1126		return winner
1127	}
1128	
1129	func countOutcomes(outcomes []raceOutcome, target error) int {
1130		n := 0
1131		for _, o := range outcomes {
1132			if errors.Is(o.err, target) {
1133				n++
1134			}
1135		}
1136		return n
1137	}
