1139	func TestSubmitReviewConcurrentRejudgmentSettlesOnce(t *testing.T) {
1140		// Repeated races make the regression independent of scheduling: whether a
1141		// contender hits the held lock or enters after release and loses on the
1142		// version check, the settled history must be identical in shape. The loop
1143		// is deterministic (no timing assumptions): every contender starts from a
1144		// barrier and the settled state is derived from stored data, not from how
1145		// many contenders reported busy versus conflict.
1146		const racers, iterations = 12, 25
1147		for iter := 0; iter < iterations; iter++ {
1148			dir := t.TempDir()
1149			mustReplay(t, dir, twoFindingsInput)
1150			// An object that already carries one real risk judgment: the race is
1151			// a concurrent rejudgment at expectedVersion 1, not a first submit.
1152			first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-0", "alice", "first real call", ReviewStatusReal, 0))
1153			if !first.Created || first.Version != 1 {
1154				t.Fatalf("iter %d setup = %+v", iter, first)
1155			}
1156			outcomes := runRejudgmentRace(t, dir, racers)
1157			verifyRaceSettlement(t, dir, outcomes, first.Revision)
1158		}
1159	}
1160	
1161	// TestSubmitReviewBusyHoldsOffThenActualVersionDecides pins the two-phase
1162	// behavior deterministically (without relying on goroutine interleaving):
1163	// while the archive is occupied, a valid rejudgment returns busy and changes
1164	// nothing; once the lock is released the same submission is accepted or
1165	// rejected by the object's actual version, never because the busy attempt was
1166	// treated as a completed rejudgment.
1167	func TestSubmitReviewBusyHoldsOffThenActualVersionDecides(t *testing.T) {
1168		dir := t.TempDir()
1169		mustReplay(t, dir, twoFindingsInput)
1170		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "hold-1", "alice", "confirmed bot war", ReviewStatusReal, 0))
1171		if !first.Created || first.Version != 1 {
1172			t.Fatalf("setup = %+v", first)
1173		}
1174		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1175		if err != nil {
1176			t.Fatal(err)
1177		}
1178	
1179		holder, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
1180		if err != nil {
1181			t.Fatal(err)
1182		}
1183		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_EX); err != nil {
1184			t.Fatal(err)
1185		}
1186	
1187		// A legal rejudgment based on version 1: while occupied it must report
1188		// busy and write nothing.
1189		contender := reviewSub("1", "0xa", "0xv", "sandwich", "hold-2", "bob", "second look says false positive", ReviewStatusFalsePositive, 1)
1190		res, err := SubmitReview(dir, contender)
1191		if !errors.Is(err, ErrBusy) {
1192			t.Fatalf("occupied archive: got %v, want ErrBusy", err)
1193		}
1194		if res.Created || res.Version != 0 || res.Revision != (ReviewRevision{}) {
1195			t.Fatalf("busy submission returned a non-empty result: %+v", res)
1196		}
1197		archiveDuring, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1198		if err != nil {
1199			t.Fatal(err)
1200		}
1201		if !reflect.DeepEqual(archiveBefore, archiveDuring) {
1202			t.Fatal("busy submission changed the archive while the lock was held")
1203		}
1204	
1205		// Release the occupation; existing review content must be intact.
1206		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_UN); err != nil {
1207			t.Fatal(err)
1208		}
1209		if err := holder.Close(); err != nil {
1210			t.Fatal(err)
1211		}
1212		held, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1213		if err != nil {
1214			t.Fatal(err)
1215		}
1216		if held.Status != ReviewStatusReal || held.Version != 1 || len(held.Revisions) != 1 {
1217			t.Fatalf("busy loss altered review content: %+v", held)
1218		}
1219		if !reflect.DeepEqual(held.Revisions[0], first.Revision) {
1220			t.Fatalf("original revision changed: %+v, want %+v", held.Revisions[0], first.Revision)
1221		}
1222	
1223		// Lock released but the object is still at version 1 (busy never
1224		// completed the rejudgment): the same submission with its original
1225		// expectedVersion 1 now succeeds as a fresh create — the busy attempt
1226		// neither consumed the submission id nor counted as a stored revision.
1227		retry, err := SubmitReview(dir, contender)
1228		if err != nil {
1229			t.Fatalf("retry after release: %v", err)
1230		}
1231		wantRev := contender.revision(2)
1232		if !retry.Created || retry.Version != 2 || !reflect.DeepEqual(retry.Revision, wantRev) {
1233			t.Fatalf("retry = %+v, want created at v2 with %+v", retry, wantRev)
1234		}
1235		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1236		if err != nil {
1237			t.Fatal(err)
1238		}
1239		if hist.Status != ReviewStatusFalsePositive || hist.Version != 2 || len(hist.Revisions) != 2 {
1240			t.Fatalf("object after retry = %q/%d with %d revisions", hist.Status, hist.Version, len(hist.Revisions))
1241		}
1242		if !reflect.DeepEqual(hist.Revisions[0], first.Revision) || !reflect.DeepEqual(hist.Revisions[1], wantRev) {
1243			t.Fatalf("revisions after retry = %+v", hist.Revisions)
1244		}
1245	
1246		// Independently, if another rejudgment had committed while we waited,
1247		// releasing the lock would not make the stale submission succeed: with
1248		// the object now at version 2, a version-1 submission conflicts and
1249		// leaves no revision.
1250		late := reviewSub("1", "0xa", "0xv", "sandwich", "hold-3", "carol", "late arrival", ReviewStatusUnreviewed, 1)
1251		if _, err := SubmitReview(dir, late); !errors.Is(err, ErrReviewConflict) {
1252			t.Fatalf("stale submission after release: got %v, want ErrReviewConflict", err)
1253		}
1254		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1255		if err != nil {
1256			t.Fatal(err)
1257		}
1258		if after.Version != 2 || len(after.Revisions) != 2 || !reflect.DeepEqual(after.Revisions, hist.Revisions) {
1259			t.Fatalf("post-release conflict appended a revision: %+v", after)
1260		}
1261	}
1262	
1263	func TestSubmitReviewFailureLeavesNoHalfRevision(t *testing.T) {
1264		dir := t.TempDir()
1265		mustReplay(t, dir, twoFindingsInput)
1266		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1267		if err != nil {
1268			t.Fatal(err)
1269		}
1270		// Unknown conclusion fails validation against archive content and must
1271		// not append anything.
1272		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xghost", "sandwich", "s", "a", "r", ReviewStatusReal, 0)); !errors.Is(err, ErrUnknownConclusion) {
1273			t.Fatalf("got %v, want ErrUnknownConclusion", err)
1274		}
1275		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1276		if err != nil {
1277			t.Fatal(err)
1278		}
1279		if !reflect.DeepEqual(before, after) {
1280			t.Fatal("failed submission modified the archive")
1281		}
