1284	// breakArchiveSave makes the archive commit fail at the save stage: the
1285	// temporary file the atomic writer creates becomes a directory, so opening
1286	// it as a regular file fails while the lock, the archived conclusion, the
1287	// review object and its revisions are all valid. This is a storage failure
1288	// at persistence time, not a validation, version-conflict or busy error.
1289	func breakArchiveSave(t *testing.T, dir string) {
1290		t.Helper()
1291		tmp := filepath.Join(dir, archiveFileName+".tmp")
1292		if err := os.Mkdir(tmp, 0o755); err != nil {
1293			t.Fatalf("break archive save: %v", err)
1294		}
1295	}
1296	
1297	func restoreArchiveSave(t *testing.T, dir string) {
1298		t.Helper()
1299		if err := os.RemoveAll(filepath.Join(dir, archiveFileName+".tmp")); err != nil {
1300			t.Fatalf("restore archive save: %v", err)
1301		}
1302	}
1303	
1304	func TestSubmitReviewSaveFailureRetriedAfterRecovery(t *testing.T) {
1305		dir := t.TempDir()
1306		mustReplay(t, dir, twoFindingsInput)
1307	
1308		// A pre-existing alert record must survive the failed and successful
1309		// submissions byte-for-byte in content.
1310		alertsBefore, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1311		if err != nil {
1312			t.Fatal(err)
1313		}
1314		if len(alertsBefore) != 2 {
1315			t.Fatalf("setup: got %d alert records, want 2", len(alertsBefore))
1316		}
1317	
1318		// Main precondition: the object is at version 1 with a real judgment and
1319		// one complete revision.
1320		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "confirmed bot", ReviewStatusReal, 0))
1321		if !first.Created || first.Version != 1 {
1322			t.Fatalf("setup submission = %+v", first)
1323		}
1324	
1325		original, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1326		if err != nil {
1327			t.Fatal(err)
1328		}
1329		if original.Status != ReviewStatusReal || original.Version != 1 || len(original.Revisions) != 1 {
1330			t.Fatalf("setup object state = %+v", original)
1331		}
1332		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1333		if err != nil {
1334			t.Fatal(err)
1335		}
1336	
1337		// Valid target, valid content, valid expected version: the only failure
1338		// is storage failing while the new revision is being archived.
1339		breakArchiveSave(t, dir)
1340		rejudgment := reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "actually a false positive", ReviewStatusFalsePositive, 1)
1341		failed, err := SubmitReview(dir, rejudgment)
1342		if err == nil {
1343			t.Fatalf("save failure must return an error, got result %+v", failed)
1344		}
1345		if errors.Is(err, ErrBusy) || errors.Is(err, ErrReviewConflict) ||
1346			errors.Is(err, ErrUnknownConclusion) || errors.Is(err, ErrSubmissionConflict) {
1347			t.Fatalf("failure must happen at the save stage, got %v", err)
1348		}
1349		if failed.Created {
1350			t.Fatalf("failed save must not report created=true: %+v", failed)
1351		}
1352		restoreArchiveSave(t, dir)
1353	
1354		// The original judgment is fully retained: still real at version 1, the
1355		// single original revision with no trace of the failed submission.
1356		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1357		if err != nil {
1358			t.Fatal(err)
1359		}
1360		if after.Status != ReviewStatusReal || after.Version != 1 {
1361			t.Fatalf("failed save advanced the object: %q/%d, want real/1", after.Status, after.Version)
1362		}
1363		if len(after.Revisions) != 1 {
1364			t.Fatalf("failed save left %d revisions: %+v", len(after.Revisions), after.Revisions)
1365		}
1366		if !reflect.DeepEqual(after.Revisions[0], original.Revisions[0]) {
1367			t.Fatalf("original revision changed: %+v, want %+v", after.Revisions[0], original.Revisions[0])
1368		}
1369		for _, rev := range after.Revisions {
1370			if rev.SubmissionID == "s-2" || rev.Operator == "bob" ||
1371				rev.Status == ReviewStatusFalsePositive || rev.Reason == "actually a false positive" {
1372				t.Fatalf("failed submission content leaked into history: %+v", rev)
1373			}
1374		}
1375		// The archived original conclusion, its detection version and the raw
1376		// swap evidence are untouched, as are the pre-existing alert records.
1377		if after.Original == nil ||
1378			after.Original.Finding.TxHash != "0xv" || after.Original.Finding.Kind != "sandwich" ||
1379			after.Original.Finding.Severity != 3 || len(after.Original.Finding.Evidence) != 3 {
1380			t.Fatalf("original conclusion/evidence changed: %+v", after.Original)
1381		}
1382		if after.Original.Version.ID != BuiltinVersionID {
1383			t.Fatalf("detection version changed: %+v", after.Original.Version)
1384		}
1385		archiveAfter, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1386		if err != nil {
1387			t.Fatal(err)
1388		}
1389		if !reflect.DeepEqual(archiveBefore, archiveAfter) {
1390			t.Fatal("failed save modified the archive file")
1391		}
1392		alertsAfter, err := AlertHistory(dir, "1", "ops", 0, 100)
1393		if err != nil {
1394			t.Fatal(err)
1395		}
1396		if !reflect.DeepEqual(alertsBefore, alertsAfter) {
1397			t.Fatalf("alert records changed: before %+v after %+v", alertsBefore, alertsAfter)
1398		}
1399	
1400		// Storage recovered: the exact same submission, same submissionId and
1401		// still expectedVersion 1, goes through as a fresh create — the failed
1402		// attempt must neither have consumed the submission id nor count as a
1403		// stored duplicate.
1404		retry, err := SubmitReview(dir, rejudgment)
1405		if err != nil {
1406			t.Fatalf("retry after recovery: %v", err)
1407		}
1408		if !retry.Created || retry.Version != 2 || retry.Status != ReviewStatusFalsePositive {
1409			t.Fatalf("retry = %+v, want created=true at version 2", retry)
1410		}
1411		wantRev := rejudgment.revision(2)
1412		if !reflect.DeepEqual(retry.Revision, wantRev) {
1413			t.Fatalf("saved revision = %+v, want %+v", retry.Revision, wantRev)
1414		}
1415	
1416		saved, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1417		if err != nil {
1418			t.Fatal(err)
1419		}
1420		if saved.Status != ReviewStatusFalsePositive || saved.Version != 2 || len(saved.Revisions) != 2 {
1421			t.Fatalf("object after retry = %q/%d with %d revisions", saved.Status, saved.Version, len(saved.Revisions))
1422		}
1423		if !reflect.DeepEqual(saved.Revisions[0], original.Revisions[0]) {
1424			t.Fatalf("original revision not retained first: %+v", saved.Revisions[0])
1425		}
1426		if !reflect.DeepEqual(saved.Revisions[1], wantRev) {
1427			t.Fatalf("appended revision = %+v, want %+v", saved.Revisions[1], wantRev)
1428		}
1429	
1430		// Sending the now-successful submission verbatim a second time is the
1431		// ordinary idempotent retry: created:false, the first successfully saved
1432		// revision returned, history unchanged.
1433		again, err := SubmitReview(dir, rejudgment)
1434		if err != nil {
1435			t.Fatalf("verbatim resend: %v", err)
1436		}
1437		if again.Created {
1438			t.Fatal("verbatim resend of a stored submission must report created=false")
1439		}
1440		if !reflect.DeepEqual(again.Revision, wantRev) || again.Version != 2 || again.Status != ReviewStatusFalsePositive {
1441			t.Fatalf("resend result = %+v", again)
1442		}
1443		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1444		if err != nil {
1445			t.Fatal(err)
1446		}
1447		if final.Version != 2 || len(final.Revisions) != 2 {
1448			t.Fatalf("verbatim resend changed history: version %d, %d revisions", final.Version, len(final.Revisions))
1449		}
1450		if !reflect.DeepEqual(final.Revisions, saved.Revisions) {
1451			t.Fatalf("verbatim resend appended a revision: %+v", final.Revisions)
1452		}
1453	}
