19	// runCLIStdin executes the real command entry with the given arguments and
20	// pipes input into the command's standard input.
21	func runCLIStdin(t *testing.T, input string, args ...string) cliResult {
22		t.Helper()
23		cmd := execCommand(args...)
24		cmd.Stdin = strings.NewReader(input)
25		var stdout, stderr bytes.Buffer
26		cmd.Stdout = &stdout
27		cmd.Stderr = &stderr
28		err := cmd.Run()
29		code := 0
30		if err != nil {
31			code = exitCode(t, err)
32		}
33		return cliResult{stdout: stdout.String(), stderr: stderr.String(), exitCode: code}
