package mevwatch

import (
	"errors"
	"strings"
	"testing"
)

func TestDupFieldScratch(t *testing.T) {
	base := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`
	cases := []struct{ name, spec, field string }{
		{"two status diff", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","status":"false_positive","expectedVersion":0}`, "status"},
		{"two status same", `{"status":"real","status":"real","chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","expectedVersion":0}`, "status"},
		{"case fold", strings.Replace(base, `"status":"real"`, `"STATUS":"real","status":"real"`, 1), "status"},
		{"unicode escape", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","status":"false_positive","expectedVersion":0}`, "status"},
		{"null then value", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":null,"status":"real","expectedVersion":0}`, "status"},
		{"dup expectedVersion", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":5,"expectedVersion":0}`, "expectedVersion"},
		{"dup chainId", `{"chainId":"1","chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "chainId"},
		{"dup submissionId", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "submissionId"},
		{"dup operator", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "operator"},
		{"dup reason", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"status and more }","reason":"r","status":"real","expectedVersion":0}`, "reason"},
		{"dup kind", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "kind"},
		{"dup block", `{"chainId":"1","blockHash":"0xa","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "blockHash"},
		{"dup tx", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "txHash"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseReviewSubmission([]byte(tc.spec))
			if !errors.Is(err, ErrReviewDuplicateField) {
				t.Fatalf("got %v, want ErrReviewDuplicateField", err)
			}
			if !strings.Contains(err.Error(), tc.field) {
				t.Fatalf("error %q must name field %q", err.Error(), tc.field)
			}
		})
	}
	// Field name appearing inside a reason string must not count.
	withName := strings.Replace(base, `"reason":"r"`, `"reason":"see status field }]"`, 1)
	if _, err := ParseReviewSubmission([]byte(withName)); err != nil {
		t.Fatalf("field name inside reason rejected: %v", err)
	}
	// Unknown field duplicated exactly is not a duplicate error — it remains
	// an unknown-field rejection from the typed decoder.
	_, err := ParseReviewSubmission([]byte(strings.Replace(base, `"expectedVersion":0`, `"expectedVersion":0,"extra":1,"extra":2`, 1)))
	if err == nil || errors.Is(err, ErrReviewDuplicateField) || !strings.Contains(err.Error(), "unknown field") {
		t.Fatalf("dup unknown field: got %v, want unknown-field error", err)
	}
}
EOF
